import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const book: Book = {
  id: 'b1',
  title: 'Dune',
  author: 'Frank Herbert',
  status: 'reading',
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'Dune' })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('Frank Herbert')).toBeInTheDocument();
  });

  it('renders status badge with correct text', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('reading')).toBeInTheDocument();
  });

  it('sets data-status attribute on badge to current status', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    const badge = screen.getByText('reading');
    expect(badge).toHaveAttribute('data-status', 'reading');
  });

  it('calls onClick with book id when clicked', () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    fireEvent.click(screen.getByRole('button', { name: /Dune by Frank Herbert/ }));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('b1');
  });

  it('calls onClick with book id when Enter is pressed', () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    fireEvent.keyDown(screen.getByRole('button', { name: /Dune by Frank Herbert/ }), { key: 'Enter' });
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('b1');
  });

  it('does not call onClick for non-Enter key presses', () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    fireEvent.keyDown(screen.getByRole('button', { name: /Dune by Frank Herbert/ }), { key: 'Space' });
    expect(handleClick).not.toHaveBeenCalled();
  });

  it('aria-label combines title and author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Dune by Frank Herbert' })).toBeInTheDocument();
  });

  it('renders finished status badge correctly', () => {
    const finishedBook: Book = { ...book, status: 'finished' };
    render(<BookCard book={finishedBook} onClick={vi.fn()} />);
    const badge = screen.getByText('finished');
    expect(badge).toHaveAttribute('data-status', 'finished');
  });
});

