import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const chips = ['Fiction', 'Non-fiction', 'Science'];

describe('ChipBar', () => {
  it('renders a button for each chip', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Non-fiction' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Science' })).toBeInTheDocument();
  });

  it('unselected chips have aria-pressed false', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Fiction' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('selected chips have aria-pressed true', () => {
    render(<ChipBar chips={chips} selected={['Fiction']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Fiction' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Non-fiction' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('clicking an unselected chip calls onSelectionChange with it added', () => {
    const onSelectionChange = vi.fn();
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={onSelectionChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(onSelectionChange).toHaveBeenCalledOnce();
    expect(onSelectionChange).toHaveBeenCalledWith(['Fiction']);
  });

  it('clicking a selected chip calls onSelectionChange with it removed', () => {
    const onSelectionChange = vi.fn();
    render(<ChipBar chips={chips} selected={['Fiction']} onSelectionChange={onSelectionChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(onSelectionChange).toHaveBeenCalledOnce();
    expect(onSelectionChange).toHaveBeenCalledWith([]);
  });

  it('preserves other selections when toggling one chip', () => {
    const onSelectionChange = vi.fn();
    render(
      <ChipBar chips={chips} selected={['Fiction', 'Science']} onSelectionChange={onSelectionChange} />,
    );
    fireEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(onSelectionChange).toHaveBeenCalledWith(['Science']);
  });

  it('adding a chip to an existing selection preserves the others', () => {
    const onSelectionChange = vi.fn();
    render(
      <ChipBar chips={chips} selected={['Science']} onSelectionChange={onSelectionChange} />,
    );
    fireEvent.click(screen.getByRole('button', { name: 'Fiction' }));
    expect(onSelectionChange).toHaveBeenCalledWith(expect.arrayContaining(['Science', 'Fiction']));
  });
});

