import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

vi.mock('../api');

const mockGetBooks = vi.mocked(api.getBooks);

describe('useBooks', () => {
  beforeEach(() => {
    mockGetBooks.mockReset();
  });

  it('starts in loading state with no books or error', () => {
    mockGetBooks.mockResolvedValue([]);
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.books).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('returns books and clears loading after getBooks resolves', async () => {
    const books = [
      { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'reading' as const },
    ];
    mockGetBooks.mockResolvedValue(books);
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.books).toEqual(books);
    expect(result.current.error).toBeNull();
  });

  it('sets error and clears loading when getBooks rejects', async () => {
    const err = new Error('fetch failed');
    mockGetBooks.mockRejectedValue(err);
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.books).toBeNull();
    expect(result.current.error).toBe(err);
  });

  it('returns empty array when getBooks resolves with no books', async () => {
    mockGetBooks.mockResolvedValue([]);
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.books).toEqual([]);
    expect(result.current.error).toBeNull();
  });
});

